public sealed record ReleaseValidationMatrix(bool SourceValidated,bool NativeBuildValidated,bool DeviceAccepted,bool StableEligible,bool ProductionSigned,bool LiveAuthorityEnabled,IReadOnlyList<string> Missing);
public static class ReleaseValidationMatrixRules{public static ReleaseValidationMatrix Create(bool sourceValidated,NativeBuildEvidence? native,DeviceAcceptanceEvidence? device){var n=native is not null&&native.BuildPassed;if(native is not null)NativeBuildEvidenceRules.Validate(native);var d=device is not null&&device.Passed;if(device is not null)DeviceAcceptanceEvidenceRules.Validate(device);if(d&&!n)throw new InvalidOperationException("Device acceptance cannot exist without native validation.");var missing=new List<string>();if(!sourceValidated)missing.Add("source-validation");if(!n)missing.Add("native-build");if(!d)missing.Add("device-acceptance");return new(sourceValidated,n,d,sourceValidated&&n&&d,native?.ProductionSigned??false,false,missing);}}
